// Guardrail 1 of 2: deterministic rules. Cheap, explainable, never "creative". Catches the obvious every time.
const s = $input.first().json;
const d = s.draft;
const p = s.page;
const issues = [];
const add = (type, quote, reason) => issues.push({ type, quote, reason, by: 'rules' });
